const money=(n:any,c:string)=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:c,maximumFractionDigits:2}).format(Number(n)||0);
const cash=(n:any)=>money(n,'ZAR');
const stockPrefix=(t:string)=>({'iPhone':'IPH','iPad':'IPD','Mac':'MAC','Apple Watch':'WAT','AirPods':'AIR','Apple Accessories':'ACC'} as any)[t]||'APL';
const nextStockId=(rows:Row[],type='iPhone')=>{const p='AS-'+stockPrefix(type)+'-'+new Date().getFullYear()+'-';const nums=rows.map(r=>r.stock_id||'').filter(x=>x.startsWith(p)).map(x=>Number(x.slice(p.length))).filter(Number.isFinite);return p+String(Math.max(0,...nums)+1).padStart(5,'0');};
