 const snap=()=>({title:title+' pricing calculation',mode:tab,currency,manufacturer,model,generation,storage,colour,grade,condition,battery:Number(battery),supplier,marketReference:n(market),purchase:n(purchase),shipping:n(shipping),delivery:n(delivery),supplierFees:n(supplierFees),paymentFees:n(paymentFees),other:n(other),warranty:n(warranty),warrantyMode,inspection:n(inspection),cleaning:n(cleaning),components:n(components),labour:n(labour),packaging:n(packaging),accessories:n(accessories),prep:n(prep),acquisitionCost:acq,refurbishmentCost:refurb,warrantyReserve:reserve,totalLandedCost:landed,targetProfitPrice:profitPrice,targetMarginPrice:marginPrice,breakEvenPrice:landed,recommendedSellingPrice:recommended,minimumSellingPrice:minimum,negotiationPrice:negotiation,promotionalPrice:promotion,tradeInValuation:tradeIn,grossProfit:gross,netContribution:gross,expectedProfit:gross,expectedMargin:margin,profitMargin:margin,markup,roi:landed?gross/landed*100:0,maximumPurchasePrice:maxBuy,competitorReference:n(competitor)||null,bulkQuantity:n(bulkQty),bulkUnitPrice:bulkUnit,decision,securityFail,security:{activationLock:lock,findMy,mdm,imei,carrier},tax:{vatRegistered:vatReg,supplierVatStatus:supplierVat,treatment:taxTreatment,taxDocumentReference:taxRef,secondHandDocumentReference:secondHandRef}});
 const reset=()=>{setTab('Selling Price');setCurrency('ZAR');setManufacturer('Apple');setModel('iPhone 14 Pro');setGeneration('14');setStorage('128 GB');setColour('');setGrade('A+');setCondition('Pre-owned');setBattery('90');setSupplier('');setMarket('10099');setPurchase('5000');setShipping('100');setDelivery('50');setSupplierFees('0');setPaymentFees('0');setOther('0');setWarranty('300');setWarrantyMode('Fixed');setInspection('50');setCleaning('30');setComponents('0');setLabour('0');setPackaging('25');setAccessories('0');setPrep('0');setTargetProfit('1500');setTargetMargin('25');setMinSell('');setCompetitor('');setPromo('');setTrade('');setBulkQty('1');setBulkDiscount('0');setLock('Clear');setFindMy('Off');setMdm('Clear');setImei('Verified');setCarrier('Unlocked');};
