 const costFields=<div className="fields">{input('Purchase price',purchase,setPurchase)}{input('Shipping',shipping,setShipping)}{input('Delivery',delivery,setDelivery)}{input('Supplier fees',supplierFees,setSupplierFees)}{input('Payment fees',paymentFees,setPaymentFees)}{input('Other costs',other,setOther)}{input('Inspection expenses',inspection,setInspection)}{input('Cleaning and sanitisation',cleaning,setCleaning)}{input('Replacement components',components,setComponents)}{input('Repair labour',labour,setLabour)}{input('Packaging',packaging,setPackaging)}{input('Accessories included',accessories,setAccessories)}{input('Data transfer / preparation',prep,setPrep)}{select('Warranty reserve method',warrantyMode,setWarrantyMode,['Fixed','Percentage'])}{input(warrantyMode==='Fixed'?'Warranty reserve (R)':'Warranty reserve (%)',warranty,setWarranty)}</div>;
