 {tab==='Profit Analysis'&&<><div className="mode-intro"><span className="mode-symbol"><AppIcon name="chart-up"/></span><div><b>Profit and return analysis</b><p>Review the full cost stack and profitability of a device or batch.</p></div></div><div className="calc-section"><h3>1. Device and sale price</h3>{phoneFields}<div className="fields">{input('Actual or expected selling price',market,setMarket)}{select('Currency',currency,setCurrency,['ZAR','USD','EUR','GBP','BWP','NAD'])}</div></div><div className="calc-section"><h3>2. Acquisition and refurbishment costs</h3>{costFields}</div><div className="calc-section"><h3>3. Profitability targets</h3><div className="fields">{input('Target profit amount',targetProfit,setTargetProfit)}{input('Target profit margin (%)',targetMargin,setTargetMargin)}{input('Minimum acceptable selling price',minSell,setMinSell)}{input('Bulk quantity',bulkQty,setBulkQty)}{input('Bulk discount (%)',bulkDiscount,setBulkDiscount)}</div></div></>}
 {tab==='Refurbishment'&&<><div className="mode-intro"><span className="mode-symbol"><AppIcon name="wrench"/></span><div><b>Refurbishment and repair costing</b><p>Record the parts, labour, inspection, cleaning and preparation costs for this device. The total flows into its selling price and profit analysis.</p></div></div><div className="calc-section"><h3>1. Device details</h3>{phoneFields}</div><div className="calc-section"><h3>2. Refurbishment work</h3><div className="fields">{input('Replacement components',components,setComponents)}{input('Repair labour',labour,setLabour)}{input('Inspection expenses',inspection,setInspection)}{input('Cleaning and sanitisation',cleaning,setCleaning)}{input('Packaging',packaging,setPackaging)}{input('Accessories included',accessories,setAccessories)}{input('Data transfer / preparation',prep,setPrep)}{select('Warranty reserve method',warrantyMode,setWarrantyMode,['Fixed','Percentage'])}{input(warrantyMode==='Fixed'?'Warranty reserve (R)':'Warranty reserve (%)',warranty,setWarranty)}</div></div><div className="calc-section"><h3>3. Updated device value</h3><div className="fields">{input('Current market resale value',market,setMarket)}{input('Expected resale after refurbishment',batteryResale,setBatteryResale)}</div></div></>}

